insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Science & Technology','Chemistry & Materials','mcq','easy','Rayon, often called ''artificial silk'', is made from','रेयॉन, जिसे प्रायः ''कृत्रिम रेशम'' कहा जाता है, किससे बनता है?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "coal, water and air", "body_hi": "कोयला, जल और वायु", "isCorrect": false}, {"id": "b", "body": "wood pulp", "body_hi": "लकड़ी की लुगदी", "isCorrect": true}, {"id": "c", "body": "silkworm cocoons", "body_hi": "रेशम कीट के कोकून", "isCorrect": false}, {"id": "d", "body": "petroleum gases", "body_hi": "पेट्रोलियम गैसें", "isCorrect": false}]'::jsonb,2,0.66,'Rayon is obtained by chemical treatment of wood pulp -- a natural source -- so it is a man-made fibre rather than a fully synthetic one; it is cheaper than silk and can be woven to look like it, and mixed with cotton or wool it makes bedsheets and carpets. Nylon, the first fully synthetic fibre, was made from coal, water and air, and polyester and acrylic come from petrochemicals.','रेयॉन लकड़ी की लुगदी -- एक प्राकृतिक स्रोत -- के रासायनिक उपचार से प्राप्त होता है, इसलिए यह पूर्णतः संश्लेषित नहीं, बल्कि मानव-निर्मित रेशा है; यह रेशम से सस्ता है और उसी जैसा दिखने वाला बुना जा सकता है, और सूती या ऊनी के साथ मिलाकर चादरें और कालीन बनते हैं। पहला पूर्णतः संश्लेषित रेशा नायलॉन कोयले, जल और वायु से बना था, और पॉलिएस्टर तथा ऐक्रिलिक पेट्रो-रसायनों से आते हैं।','l1-sci-rayon-wood-pulp','original_pattern_matched','NCERT Class VIII, Science (Synthetic Fibres and Plastics).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','easy','Consider the following statements about plastics:','प्लास्टिक के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Polythene and PVC are thermoplastics, which can be softened by heating and moulded again.", "Bakelite is a thermosetting plastic used for electrical switches and the handles of utensils, since it is a poor conductor of heat and electricity.", "Melamine is a thermoplastic that melts easily, which makes it unsuitable for kitchenware."], "statements_hi": ["पॉलिथीन और PVC तापसुघट्य (thermoplastic) हैं, जिन्हें गर्म करके नरम किया और फिर से ढाला जा सकता है।", "बेकेलाइट एक तापदृढ़ (thermosetting) प्लास्टिक है, जो ऊष्मा और विद्युत का कुचालक होने के कारण बिजली के स्विचों और बर्तनों के हत्थों में प्रयुक्त होता है।", "मेलामाइन एक तापसुघट्य प्लास्टिक है जो आसानी से पिघल जाता है, इसलिए रसोई के बर्तनों के लिए अनुपयुक्त है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: thermoplastics deform easily on heating and can be recycled into new shapes, while thermosetting plastics, once moulded, cannot be softened again. Statement 3 is wrong: melamine is a thermosetting plastic that resists fire and tolerates heat better than other plastics, which is why it is used for floor tiles, kitchenware and fire-resistant fabrics.','कथन 1 और 2 सही हैं: तापसुघट्य प्लास्टिक गर्म करने पर आसानी से रूप बदलते हैं और नए आकारों में पुनर्चक्रित हो सकते हैं, जबकि तापदृढ़ प्लास्टिक एक बार ढलने के बाद फिर नरम नहीं होते। कथन 3 गलत है: मेलामाइन एक तापदृढ़ प्लास्टिक है जो आग का प्रतिरोध करता है और अन्य प्लास्टिक से बेहतर ताप सहता है, इसीलिए यह फ़र्श की टाइलों, रसोई के बर्तनों और अग्निरोधी कपड़ों में प्रयुक्त होता है।','l1-sci-thermoplastic-thermosetting','original_pattern_matched','NCERT Class VIII, Science (Synthetic Fibres and Plastics).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','easy','Consider the following statements about storing reactive elements:','अभिक्रियाशील तत्वों के भंडारण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Sodium is stored under kerosene, because it reacts vigorously with the oxygen and moisture in air.", "White phosphorus is stored under water, because it catches fire on exposure to air."], "statements_hi": ["सोडियम को केरोसिन में रखा जाता है, क्योंकि यह वायु की ऑक्सीजन और नमी से तीव्र अभिक्रिया करता है।", "श्वेत फ़ॉस्फ़ोरस को पानी में रखा जाता है, क्योंकि यह वायु के संपर्क में आते ही आग पकड़ लेता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Sodium and potassium are so reactive that they catch fire if kept in the open, and they react violently with water, so kerosene, which does not react with them, keeps them away from both air and water. Phosphorus, a non-metal, does not react with water, so a covering of water shields it from the oxygen of the air: how a substance is stored depends on what it reacts with.','दोनों कथन सही हैं। सोडियम और पोटैशियम इतने अभिक्रियाशील हैं कि खुले में रखने पर आग पकड़ लेते हैं, और पानी से भी तीव्र अभिक्रिया करते हैं, इसलिए केरोसिन, जो उनसे अभिक्रिया नहीं करता, उन्हें वायु और जल दोनों से दूर रखता है। अधातु फ़ॉस्फ़ोरस पानी से अभिक्रिया नहीं करता, इसलिए पानी की परत उसे वायु की ऑक्सीजन से बचाती है: किसी पदार्थ का भंडारण इस पर निर्भर है कि वह किससे अभिक्रिया करता है।','l1-sci-sodium-kerosene-phosphorus-water','original_pattern_matched','NCERT Class VIII, Science (Materials: Metals and Non-Metals).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','easy','Consider the following statements about the tarnishing of metals:','धातुओं के मलिन (tarnish) होने के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Silver articles turn black in air, owing to a coating of silver sulphide.", "Copper vessels slowly acquire a green coating of basic copper carbonate in moist air."], "statements_hi": ["वायु में चाँदी की वस्तुएँ सिल्वर सल्फ़ाइड की परत के कारण काली पड़ जाती हैं।", "नम वायु में ताँबे के बर्तनों पर धीरे-धीरे क्षारीय कॉपर कार्बोनेट की हरी परत चढ़ जाती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct: silver reacts with sulphur compounds in the air, and copper with the moisture and carbon dioxide in it -- both are forms of corrosion, the slow attack of a metal by substances around it. That is why old copper vessels are cleaned with lemon or tamarind juice, whose acids dissolve the green basic carbonate; gold and platinum, being very unreactive, stay bright.','दोनों कथन सही हैं: चाँदी वायु के सल्फ़र यौगिकों से, और ताँबा उसकी नमी तथा कार्बन डाइऑक्साइड से अभिक्रिया करता है -- दोनों संक्षारण के रूप हैं, यानी आसपास के पदार्थों द्वारा धातु पर धीमा आक्रमण। इसीलिए पुराने ताँबे के बर्तन नींबू या इमली के रस से साफ़ किए जाते हैं, जिनके अम्ल हरे क्षारीय कार्बोनेट को घोल देते हैं; अत्यंत कम अभिक्रियाशील होने के कारण सोना और प्लैटिनम चमकदार रहते हैं।','l1-sci-silver-copper-tarnish','original_pattern_matched','NCERT Class X, Science (Metals and Non-metals).','draft'),
('upsc','Science & Technology','Chemistry & Materials','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Water should not be used to put out a fire involving electrical equipment.", "assertion_hi": "बिजली के उपकरणों में लगी आग बुझाने के लिए पानी का उपयोग नहीं करना चाहिए।", "reason": "Water conducts electricity and can give those fighting the fire an electric shock.", "reason_hi": "पानी विद्युत का चालक है और आग बुझाने वालों को बिजली का झटका दे सकता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. For electrical fires, and for fires of oil and petrol, carbon dioxide is preferred: being heavier than oxygen it covers the fire like a blanket, cutting off the supply of air, and it does not harm the equipment. Water works well on burning wood and paper because it cools the fuel below its ignition temperature, and its vapour also surrounds the fire.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। बिजली की आग के लिए, और तेल तथा पेट्रोल की आग के लिए, कार्बन डाइऑक्साइड को प्राथमिकता दी जाती है: ऑक्सीजन से भारी होने के कारण यह आग को कंबल की तरह ढक कर वायु की आपूर्ति रोक देती है, और उपकरण को हानि नहीं पहुँचाती। जलती लकड़ी और काग़ज़ पर पानी अच्छा काम करता है, क्योंकि यह ईंधन को उसके ज्वलन ताप से नीचे ठंडा कर देता है, और इसकी भाप भी आग को घेर लेती है।','l1-sci-water-electrical-fire','original_pattern_matched','NCERT Class VIII, Science (Combustion and Flame).','draft'),
('upsc','Science & Technology','Chemistry & Materials','mcq','medium','Plaster of Paris must be stored in a moisture-proof container because','प्लास्टर ऑफ़ पेरिस को नमी-रोधी पात्र में रखना आवश्यक है, क्योंकि','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "it gives off a poisonous gas when it meets moist air", "body_hi": "नम वायु के संपर्क में यह विषैली गैस छोड़ता है", "isCorrect": false}, {"id": "b", "body": "it dissolves completely in water and is lost", "body_hi": "यह पानी में पूरी तरह घुलकर नष्ट हो जाता है", "isCorrect": false}, {"id": "c", "body": "it reacts with carbon dioxide to form chalk powder", "body_hi": "यह कार्बन डाइऑक्साइड से अभिक्रिया करके चॉक का चूर्ण बनाता है", "isCorrect": false}, {"id": "d", "body": "it absorbs water and sets into a hard mass of gypsum", "body_hi": "यह पानी सोखकर जिप्सम के कठोर पिंड में जम जाता है", "isCorrect": true}]'::jsonb,2,0.66,'Plaster of Paris is calcium sulphate hemihydrate, made by heating gypsum; mixed with water it takes the water back and sets within minutes into a hard solid -- the property that makes it useful for supporting fractured bones, for toys, decorative materials and smooth surfaces. The same property ruins it in storage: moisture from the air would make it set in the bag.','प्लास्टर ऑफ़ पेरिस कैल्शियम सल्फ़ेट हेमीहाइड्रेट है, जो जिप्सम को गर्म करके बनता है; पानी मिलाने पर यह पानी वापस ले लेता है और कुछ ही मिनटों में कठोर ठोस में जम जाता है -- यही गुण इसे टूटी हड्डियों को सहारा देने, खिलौनों, सजावटी सामग्री और चिकनी सतहों के लिए उपयोगी बनाता है। यही गुण भंडारण में इसे बिगाड़ देता है: वायु की नमी इसे थैले में ही जमा देगी।','l1-sci-plaster-of-paris-storage','original_pattern_matched','NCERT Class X, Science (Acids, Bases and Salts).','draft'),
('upsc','Science & Technology','Chemistry & Materials','mcq','medium','Cans for storing food are made of iron electroplated with tin, rather than with zinc, mainly because','भोजन रखने के डिब्बे जस्ते के बजाय टिन चढ़े लोहे के बनाए जाते हैं, मुख्यतः क्योंकि','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "tin, being less reactive, keeps the food off the iron", "body_hi": "कम अभिक्रियाशील टिन भोजन को लोहे से दूर रखता है", "isCorrect": true}, {"id": "b", "body": "tin is cheaper and more plentiful than zinc", "body_hi": "टिन जस्ते से सस्ता और अधिक उपलब्ध है", "isCorrect": false}, {"id": "c", "body": "tin makes the can strong enough to resist being dented", "body_hi": "टिन डिब्बे को इतना मज़बूत बनाता है कि उसमें गड्ढा न पड़े", "isCorrect": false}, {"id": "d", "body": "zinc cannot be electroplated onto iron at all", "body_hi": "लोहे पर जस्ते की विद्युत-लेपन हो ही नहीं सकती", "isCorrect": false}]'::jsonb,2,0.66,'Tin is less reactive than iron, so a tin coating keeps the food from coming into contact with iron and protects it from spoiling. Zinc, more reactive than iron, protects iron in the open -- galvanised iron sheets and pipes -- but it would react with the acids in food. Tin is in fact the costlier metal; it is used for what it does, not for its price.','टिन लोहे से कम अभिक्रियाशील है, इसलिए टिन की परत भोजन को लोहे के संपर्क में आने से रोकती और उसे ख़राब होने से बचाती है। लोहे से अधिक अभिक्रियाशील जस्ता खुले में लोहे की रक्षा करता है -- जस्तीकृत लोहे की चादरें और पाइप -- पर वह भोजन के अम्लों से अभिक्रिया करेगा। वास्तव में टिन महँगी धातु है; उसका उपयोग उसके गुण के कारण होता है, कीमत के कारण नहीं।','l1-sci-tin-plated-food-cans','original_pattern_matched','NCERT Class VIII, Science (Chemical Effects of Electric Current).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','medium','Consider the following statements about some chemical reactions in daily life:','दैनिक जीवन की कुछ रासायनिक अभिक्रियाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Quicklime (calcium oxide) reacts with water vigorously, giving out a great deal of heat.", "Walls whitewashed with slaked lime get a shiny finish after two or three days, as calcium hydroxide reacts with carbon dioxide in the air to form calcium carbonate.", "White silver chloride turns grey in sunlight, as it decomposes into silver and chlorine -- a reaction once used in black-and-white photography."], "statements_hi": ["बिना बुझा चूना (कैल्शियम ऑक्साइड) पानी से तीव्र अभिक्रिया करके बहुत ऊष्मा छोड़ता है।", "बुझे चूने से पुती दीवारें दो-तीन दिन बाद चमकदार हो जाती हैं, क्योंकि कैल्शियम हाइड्रॉक्साइड वायु की कार्बन डाइऑक्साइड से अभिक्रिया करके कैल्शियम कार्बोनेट बनाता है।", "सफ़ेद सिल्वर क्लोराइड धूप में धूसर हो जाता है, क्योंकि यह सिल्वर और क्लोरीन में अपघटित होता है -- यह अभिक्रिया कभी श्वेत-श्याम फ़ोटोग्राफ़ी में प्रयुक्त होती थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The first is an exothermic combination reaction, the second a slow reaction with the air that hardens the whitewash, and the third a decomposition reaction driven by light. The heat from slaking lime is enough to burn the skin, which is why lime is handled with care.','तीनों कथन सही हैं। पहली ऊष्माक्षेपी संयोजन अभिक्रिया है, दूसरी वायु से धीमी अभिक्रिया है जो सफ़ेदी को कठोर बनाती है, और तीसरी प्रकाश से होने वाली अपघटन अभिक्रिया है। चूना बुझाते समय निकली ऊष्मा त्वचा जला सकती है, इसीलिए चूने को सावधानी से सँभाला जाता है।','l1-sci-quicklime-whitewash-silver-chloride','original_pattern_matched','NCERT Class X, Science (Chemical Reactions and Equations).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','medium','Consider the following statements about electricity and chemical change:','विद्युत और रासायनिक परिवर्तन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Distilled water is a poor conductor of electricity, while tap water conducts because of the salts dissolved in it.", "Chromium is electroplated onto car parts, taps and cycle handlebars because it is shiny, does not corrode and resists scratches.", "In electroplating, the object to be plated is connected to the positive terminal of the battery."], "statements_hi": ["आसुत जल विद्युत का कुचालक है, जबकि नल का पानी उसमें घुले लवणों के कारण चालन करता है।", "कार के पुर्ज़ों, नलों और साइकिल के हैंडल पर क्रोमियम की विद्युत-लेपन की जाती है, क्योंकि वह चमकदार है, उसका संक्षारण नहीं होता और वह खरोंच का प्रतिरोध करता है।", "विद्युत-लेपन में लेपित की जाने वाली वस्तु को बैटरी के धन टर्मिनल से जोड़ा जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: chromium is costly, so a thin layer of it is deposited over a cheaper metal. Statement 3 is wrong: the object is made the negative electrode, where metal ions from the solution are deposited on it, while a plate of the plating metal is joined to the positive terminal and slowly dissolves to keep the solution''s strength up.','कथन 1 और 2 सही हैं: क्रोमियम महँगा है, इसलिए उसकी एक पतली परत किसी सस्ती धातु पर चढ़ाई जाती है। कथन 3 गलत है: वस्तु को ऋण इलेक्ट्रोड बनाया जाता है, जहाँ विलयन के धातु आयन उस पर जमते हैं, जबकि लेपन वाली धातु की प्लेट धन टर्मिनल से जुड़ी रहती है और विलयन की सांद्रता बनाए रखने के लिए धीरे-धीरे घुलती है।','l1-sci-electroplating-distilled-water','original_pattern_matched','NCERT Class VIII, Science (Chemical Effects of Electric Current).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','medium','Consider the following statements about combustion and fire:','दहन और आग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The outermost zone of a candle flame, where combustion is complete, is the hottest part of the flame.", "Goldsmiths blow the outermost zone of a flame onto gold and silver to melt them.", "Carbon dioxide puts out a fire partly because, being heavier than oxygen, it covers the fire and cuts off the supply of air."], "statements_hi": ["मोमबत्ती की लौ का सबसे बाहरी भाग, जहाँ दहन पूर्ण होता है, लौ का सबसे गर्म भाग है।", "सुनार सोना और चाँदी पिघलाने के लिए लौ के सबसे बाहरी भाग को उन पर फूँकते हैं।", "कार्बन डाइऑक्साइड आंशिक रूप से इसलिए आग बुझाती है कि ऑक्सीजन से भारी होने के कारण वह आग को ढक कर वायु की आपूर्ति रोक देती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. A flame has three zones: the dark innermost zone of unburnt wax vapour, the luminous middle zone of partial combustion, and the non-luminous outer zone of complete combustion. Fire needs fuel, air and heat enough to reach the ignition temperature; an extinguisher works by removing one or more of these -- carbon dioxide both cuts off air and cools the fuel.','तीनों कथन सही हैं। लौ के तीन भाग होते हैं: बिना जली मोम-वाष्प का काला सबसे भीतरी भाग, आंशिक दहन का दीप्त मध्य भाग, और पूर्ण दहन का अदीप्त बाहरी भाग। आग को ईंधन, वायु और ज्वलन ताप तक पहुँचने लायक़ ऊष्मा चाहिए; अग्निशामक इनमें से एक या अधिक को हटाकर काम करता है -- कार्बन डाइऑक्साइड वायु भी रोकती है और ईंधन को ठंडा भी करती है।','l1-sci-candle-flame-zones-co2','original_pattern_matched','NCERT Class VIII, Science (Combustion and Flame).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','medium','Consider the following statements about acids in daily life:','दैनिक जीवन में अम्लों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["An ant''s sting injects methanoic (formic) acid, and the pain is relieved by rubbing a mild base such as baking soda on it.", "The stinging hairs of nettle leaves also inject methanoic acid.", "Tooth decay starts when the pH in the mouth falls below about 5.5.", "Soil that is too acidic is treated with quicklime, slaked lime or chalk."], "statements_hi": ["चींटी का डंक मेथेनॉइक (फ़ॉर्मिक) अम्ल डालता है, और उस पर बेकिंग सोडा जैसा दुर्बल क्षार मलने से दर्द में राहत मिलती है।", "बिच्छू-बूटी (नेटल) की पत्तियों के डंक वाले रोम भी मेथेनॉइक अम्ल डालते हैं।", "मुँह का pH लगभग 5.5 से नीचे गिरने पर दाँतों का क्षय आरंभ होता है।", "अत्यधिक अम्लीय मिट्टी को बिना बुझे चूने, बुझे चूने या खड़िया से उपचारित किया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct; each is a neutralisation. Bacteria in the mouth break down sugar and food particles left after eating into acids that dissolve tooth enamel, the hardest substance in the body -- which is why toothpastes, being basic, help. A nettle sting is traditionally rubbed with the leaf of the dock plant, which often grows beside it, and farmers correct sour soil with bases so that crops can grow.','चारों कथन सही हैं; हर एक उदासीनीकरण है। मुँह के जीवाणु खाने के बाद बचे शर्करा और भोजन कणों को अम्लों में तोड़ते हैं, जो शरीर के सबसे कठोर पदार्थ, दाँतों के इनेमल, को घोलते हैं -- इसीलिए क्षारीय होने के कारण टूथपेस्ट सहायक हैं। बिच्छू-बूटी के डंक पर परंपरागत रूप से डॉक पौधे की पत्ती मली जाती है, जो प्रायः उसके पास ही उगता है, और किसान खट्टी मिट्टी को क्षारों से सुधारते हैं ताकि फ़सलें उग सकें।','l1-sci-acids-daily-life-stings-teeth-soil','original_pattern_matched','NCERT Class VII, Science (Acids, Bases and Salts); NCERT Class X, Science (Acids, Bases and Salts).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','medium','Consider the following statements about ethanoic acid and esters:','एथेनॉइक अम्ल और एस्टरों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Esters, formed when an acid reacts with an alcohol, are sweet-smelling and are used in perfumes and flavourings.", "Pure ethanoic acid freezes in cold weather, which gives it the name ''glacial acetic acid''.", "Ethanoic acid is a weak acid, ionising only partly in water.", "Esters react with an alkali to give back the alcohol and a salt of the acid, the reaction used to make soap."], "statements_hi": ["अम्ल और ऐल्कोहॉल की अभिक्रिया से बनने वाले एस्टर मीठी गंध वाले होते हैं और इत्रों तथा सुगंधकों में प्रयुक्त होते हैं।", "शुद्ध एथेनॉइक अम्ल ठंडे मौसम में जम जाता है, जिससे उसे ''ग्लेशियल ऐसीटिक अम्ल'' नाम मिला।", "एथेनॉइक अम्ल एक दुर्बल अम्ल है, जो पानी में केवल आंशिक रूप से आयनित होता है।", "एस्टर क्षार से अभिक्रिया करके ऐल्कोहॉल और अम्ल का लवण वापस देते हैं, यही अभिक्रिया साबुन बनाने में प्रयुक्त होती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Pure ethanoic acid melts at about 290 K, around 17 degrees Celsius, so it often freezes in winter in cold climates. Esterification needs an acid catalyst; its reverse with an alkali, called saponification, turns fats and oils -- esters of fatty acids -- into soap.','चारों कथन सही हैं। शुद्ध एथेनॉइक अम्ल लगभग 290 K, यानी लगभग 17 डिग्री सेल्सियस, पर पिघलता है, इसलिए ठंडी जलवायु में सर्दियों में प्रायः जम जाता है। एस्टरीकरण के लिए अम्ल उत्प्रेरक चाहिए; क्षार के साथ इसकी उलटी अभिक्रिया, साबुनीकरण, वसाओं और तेलों -- वसीय अम्लों के एस्टरों -- को साबुन में बदलती है।','l1-sci-ethanoic-acid-esters','original_pattern_matched','NCERT Class X, Science (Carbon and its Compounds).','draft'),
('upsc','Science & Technology','Chemistry & Materials','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Ethanol meant for industrial use is mixed with methanol and coloured with a blue dye.", "assertion_hi": "औद्योगिक उपयोग के लिए बने एथेनॉल में मेथेनॉल मिलाया जाता है और उसे नीले रंग से रंगा जाता है।", "reason": "Methanol is poisonous: even small amounts can cause blindness, and larger amounts death, so the mixture is unfit for drinking.", "reason_hi": "मेथेनॉल विषैला है: थोड़ी मात्रा भी अंधापन, और अधिक मात्रा मृत्यु का कारण बन सकती है, इसलिए यह मिश्रण पीने योग्य नहीं रहता।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. This ''denatured alcohol'' prevents the misuse of cheap industrial ethanol for drinking, and the blue dye lets it be identified at a glance. In the liver, methanol is oxidised to methanal, which reacts with the components of cells; it also affects the optic nerve, which is why spurious liquor laced with methanol causes blindness.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। यह ''विकृतीकृत ऐल्कोहॉल'' (denatured alcohol) सस्ते औद्योगिक एथेनॉल के पीने के लिए दुरुपयोग को रोकता है, और नीला रंग उसे एक नज़र में पहचानने देता है। यकृत में मेथेनॉल मेथेनैल में ऑक्सीकृत होता है, जो कोशिकाओं के घटकों से अभिक्रिया करता है; यह दृष्टि तंत्रिका को भी प्रभावित करता है, इसीलिए मेथेनॉल मिली नक़ली शराब से अंधापन होता है।','l1-sci-denatured-alcohol-methanol','original_pattern_matched','NCERT Class X, Science (Carbon and its Compounds).','draft'),
('upsc','Science & Technology','Chemistry & Materials','statement_based','hard','Consider the following statements about the development of the periodic table:','आवर्त सारणी के विकास के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Mendeleev arranged the elements in order of increasing atomic mass.", "Mendeleev left gaps for undiscovered elements, such as ''eka-aluminium'' and ''eka-silicon'', later found as gallium and germanium.", "The modern periodic law states that the properties of elements are a periodic function of their atomic number.", "Newlands'' law of octaves was found to work only up to calcium."], "statements_hi": ["मेंडलीफ़ ने तत्वों को बढ़ते परमाणु द्रव्यमान के क्रम में व्यवस्थित किया।", "मेंडलीफ़ ने अज्ञात तत्वों के लिए रिक्त स्थान छोड़े, जैसे ''एका-ऐलुमिनियम'' और ''एका-सिलिकॉन'', जो बाद में गैलियम और जर्मेनियम के रूप में मिले।", "आधुनिक आवर्त नियम कहता है कि तत्वों के गुणधर्म उनके परमाणु क्रमांक के आवर्ती फलन हैं।", "न्यूलैंड्स का अष्टक नियम केवल कैल्शियम तक ही लागू पाया गया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The accurate predictions of the properties of gallium and germanium won Mendeleev''s table wide acceptance, but ordering by atomic mass left anomalies, such as cobalt before nickel and the position of hydrogen and isotopes. Henry Moseley showed in 1913 that atomic number is the more fundamental property, and arranging elements by it removed these anomalies.','चारों कथन सही हैं। गैलियम और जर्मेनियम के गुणधर्मों की सटीक भविष्यवाणियों ने मेंडलीफ़ की सारणी को व्यापक स्वीकृति दिलाई, पर परमाणु द्रव्यमान के क्रम से कुछ विसंगतियाँ रहीं, जैसे निकेल से पहले कोबाल्ट और हाइड्रोजन तथा समस्थानिकों का स्थान। हेनरी मोज़ले ने 1913 में दिखाया कि परमाणु क्रमांक अधिक मूलभूत गुण है, और उसके अनुसार तत्वों को रखने से ये विसंगतियाँ दूर हो गईं।','l1-sci-periodic-table-history','original_pattern_matched','NCERT Class X, Science (Periodic Classification of Elements, earlier editions).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','mcq','easy','The alternating current supplied to homes in India has a frequency of','भारत में घरों को दी जाने वाली प्रत्यावर्ती धारा की आवृत्ति कितनी है?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "60 Hz", "body_hi": "60 हर्ट्ज़", "isCorrect": false}, {"id": "b", "body": "100 Hz", "body_hi": "100 हर्ट्ज़", "isCorrect": false}, {"id": "c", "body": "50 Hz", "body_hi": "50 हर्ट्ज़", "isCorrect": true}, {"id": "d", "body": "25 Hz", "body_hi": "25 हर्ट्ज़", "isCorrect": false}]'::jsonb,2,0.66,'Household supply in India is at 220 volts and 50 hertz: the current changes direction every 1/100 of a second, completing 50 cycles each second. Countries such as the USA use 60 Hz and about 120 V, which is why some appliances need adapters or converters abroad; alternating current is used because transformers can raise or lower its voltage easily.','भारत में घरेलू आपूर्ति 220 वोल्ट और 50 हर्ट्ज़ पर होती है: धारा हर 1/100 सेकंड में दिशा बदलती है, और हर सेकंड 50 चक्र पूरे करती है। अमेरिका जैसे देश 60 हर्ट्ज़ और लगभग 120 वोल्ट का उपयोग करते हैं, इसीलिए कुछ उपकरणों को विदेश में एडैप्टर या कन्वर्टर चाहिए; प्रत्यावर्ती धारा इसलिए प्रयुक्त होती है कि ट्रांसफ़ॉर्मर उसका वोल्टेज आसानी से बढ़ा या घटा सकते हैं।','l1-sci-ac-50-hz-220-v','original_pattern_matched','NCERT Class X, Science (Magnetic Effects of Electric Current).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','statement_based','easy','Consider the following statements about pressure:','दाब के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A sharp knife cuts more easily than a blunt one, because the same force acts on a smaller area and so exerts more pressure.", "School bags have wide straps so that the weight is spread over a larger area, reducing the pressure on the shoulders.", "Dams are made thicker at the bottom, because the pressure of water increases with depth."], "statements_hi": ["तेज़ चाकू भोथरे चाकू से आसानी से काटता है, क्योंकि वही बल कम क्षेत्रफल पर लगकर अधिक दाब डालता है।", "स्कूल बस्तों की पट्टियाँ चौड़ी होती हैं ताकि भार बड़े क्षेत्रफल पर फैले और कंधों पर दाब घटे।", "बाँधों को तल पर मोटा बनाया जाता है, क्योंकि पानी का दाब गहराई के साथ बढ़ता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct: pressure is force per unit area, so it rises when the same force acts on a smaller area and falls when the area is larger. A liquid presses on the walls of its container, and the pressure at a point depends on the depth below the surface, so the lowest part of a dam must withstand the greatest push.','तीनों कथन सही हैं: दाब प्रति इकाई क्षेत्रफल पर बल है, इसलिए वही बल कम क्षेत्रफल पर लगने पर दाब बढ़ता और बड़े क्षेत्रफल पर घटता है। द्रव अपने पात्र की दीवारों पर दाब डालता है, और किसी बिंदु पर दाब सतह से उसकी गहराई पर निर्भर करता है, इसलिए बाँध के सबसे निचले भाग को सबसे बड़ा धक्का सहना पड़ता है।','l1-sci-pressure-knife-straps-dams','original_pattern_matched','NCERT Class VIII, Science (Force and Pressure).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','statement_based','easy','Consider the following statements about friction:','घर्षण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Rolling friction is smaller than sliding friction, which is why ball bearings are used between moving parts of machines.", "The treads on tyres increase friction and so improve their grip on the road.", "Friction is always a nuisance and serves no useful purpose."], "statements_hi": ["लोटनिक घर्षण सर्पी घर्षण से कम होता है, इसीलिए मशीनों के गतिशील भागों के बीच बॉल बेयरिंग लगाए जाते हैं।", "टायरों पर बने खाँचे (tread) घर्षण बढ़ाकर सड़क पर उनकी पकड़ सुधारते हैं।", "घर्षण सदा एक बाधा है और किसी उपयोगी काम का नहीं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Statement 3 is wrong: without friction we could not walk, write, hold anything or stop a vehicle, and a matchstick could not be lit; friction is reduced where it wastes energy and causes wear -- by lubricants, ball bearings and streamlined shapes -- and increased where grip is needed.','कथन 1 और 2 सही हैं। कथन 3 गलत है: घर्षण के बिना हम चल, लिख, कुछ पकड़ या कोई वाहन रोक नहीं सकते, और माचिस की तीली नहीं जल सकती; जहाँ घर्षण ऊर्जा बर्बाद करता और घिसाव करता है, वहाँ उसे स्नेहकों, बॉल बेयरिंग और धारारेखीय आकारों से घटाया जाता है, और जहाँ पकड़ चाहिए वहाँ बढ़ाया जाता है।','l1-sci-friction-rolling-treads','original_pattern_matched','NCERT Class VIII, Science (Friction).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','mcq','medium','A 2 kW room heater is used for 3 hours a day for 30 days. If electricity costs ₹6 per unit, the cost of running it is','2 किलोवाट का एक रूम हीटर 30 दिनों तक प्रतिदिन 3 घंटे चलाया जाता है। यदि बिजली ₹6 प्रति यूनिट हो, तो इसे चलाने का ख़र्च कितना है?','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "₹1,080", "body_hi": "₹1,080", "isCorrect": true}, {"id": "b", "body": "₹108", "body_hi": "₹108", "isCorrect": false}, {"id": "c", "body": "₹360", "body_hi": "₹360", "isCorrect": false}, {"id": "d", "body": "₹10,800", "body_hi": "₹10,800", "isCorrect": false}]'::jsonb,2,0.66,'Energy used = power x time = 2 kW x 3 h x 30 = 180 kilowatt-hours, or 180 units, since one ''unit'' of electricity on a bill is one kilowatt-hour; at ₹6 a unit the cost is 180 x 6 = ₹1,080. Forgetting the 30 days gives only a day''s cost of ₹36, and working in watts without converting to kilowatts gives an answer a thousand times too large.','उपयोग की गई ऊर्जा = शक्ति x समय = 2 किलोवाट x 3 घंटे x 30 = 180 किलोवाट-घंटा, यानी 180 यूनिट, क्योंकि बिल में बिजली की एक ''यूनिट'' एक किलोवाट-घंटा है; ₹6 प्रति यूनिट पर ख़र्च 180 x 6 = ₹1,080 है। 30 दिन भूल जाने पर ₹36 प्रतिदिन आता है, और वाट को किलोवाट में बदले बिना गणना करने पर उत्तर हज़ार गुना बड़ा आता है।','l1-sci-electricity-bill-kwh','original_pattern_matched','NCERT Class X, Science (Electricity).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','statement_based','medium','Consider the following statements about electric wiring in a home:','घर की विद्युत वायरिंग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A fuse is a wire of low melting point connected in series with the circuit, which melts and breaks the circuit when too large a current flows.", "Household appliances are connected in parallel, so that each gets the same voltage and can be switched on or off independently.", "The earth wire carries current all the time during normal use of an appliance."], "statements_hi": ["फ़्यूज़ कम गलनांक वाला तार है जो परिपथ के साथ श्रेणी में जुड़ा होता है, और बहुत अधिक धारा बहने पर पिघलकर परिपथ तोड़ देता है।", "घरेलू उपकरण समानांतर क्रम में जोड़े जाते हैं, ताकि हर एक को समान वोल्टेज मिले और उसे स्वतंत्र रूप से चालू या बंद किया जा सके।", "किसी उपकरण के सामान्य उपयोग के दौरान भू-संपर्क (earth) तार में हर समय धारा बहती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: overloading or a short circuit makes the current rise sharply, and the fuse -- or a miniature circuit breaker -- protects the wiring and appliances from overheating and fire. Statement 3 is wrong: the earth wire, connected to the metal body of an appliance, carries current only when there is a fault, such as a live wire touching the body; it then leads the leakage current safely to the ground, protecting the user from a severe shock.','कथन 1 और 2 सही हैं: अतिभार या लघुपथन (short circuit) से धारा तेज़ी से बढ़ती है, और फ़्यूज़ -- या लघु परिपथ वियोजक (MCB) -- वायरिंग और उपकरणों को अधिक गर्म होने और आग से बचाता है। कथन 3 गलत है: उपकरण के धातु के ढाँचे से जुड़ा भू-संपर्क तार केवल ख़राबी होने पर, जैसे विद्युन्मय तार के ढाँचे को छू जाने पर, धारा ले जाता है; तब वह रिसने वाली धारा को सुरक्षित रूप से धरती में ले जाकर उपयोगकर्ता को तीव्र झटके से बचाता है।','l1-sci-fuse-parallel-earth-wire','original_pattern_matched','NCERT Class X, Science (Electricity; Magnetic Effects of Electric Current).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','statement_based','medium','Consider the following statements about electromagnetism:','विद्युत-चुंबकत्व के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["An electric motor converts electrical energy into mechanical energy.", "An electric generator works on the principle that a current-carrying conductor placed in a magnetic field experiences a force.", "An electromagnet made with a soft iron core keeps its magnetism after the current is switched off."], "statements_hi": ["विद्युत मोटर विद्युत ऊर्जा को यांत्रिक ऊर्जा में बदलती है।", "विद्युत जनित्र इस सिद्धांत पर काम करता है कि चुंबकीय क्षेत्र में रखा धारावाही चालक बल अनुभव करता है।", "नरम लोहे की क्रोड वाला विद्युत-चुंबक धारा बंद करने के बाद भी अपना चुंबकत्व बनाए रखता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 describes the motor: the force on a current-carrying conductor in a magnetic field is what turns its coil. A generator works on electromagnetic induction -- a coil rotated in a magnetic field has a current induced in it -- and so converts mechanical energy into electrical energy. Statement 3 is wrong: soft iron loses its magnetism almost as soon as the current stops, which is exactly why it is used in electromagnets for cranes, bells and relays that must be switched on and off.','केवल कथन 1 सही है। कथन 2 मोटर का वर्णन करता है: चुंबकीय क्षेत्र में धारावाही चालक पर लगने वाला बल ही उसकी कुंडली को घुमाता है। जनित्र विद्युत-चुंबकीय प्रेरण पर काम करता है -- चुंबकीय क्षेत्र में घुमाई गई कुंडली में धारा प्रेरित होती है -- और इस प्रकार यांत्रिक ऊर्जा को विद्युत ऊर्जा में बदलता है। कथन 3 गलत है: धारा रुकते ही नरम लोहा लगभग तुरंत अपना चुंबकत्व खो देता है, ठीक इसी कारण वह क्रेनों, घंटियों और रिले के विद्युत-चुंबकों में प्रयुक्त होता है, जिन्हें चालू और बंद करना पड़ता है।','l1-sci-motor-generator-electromagnet','original_pattern_matched','NCERT Class X, Science (Magnetic Effects of Electric Current).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','statement_based','medium','Consider the following statements about the heating effect of electric current:','विद्युत धारा के तापीय प्रभाव के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The filament of an incandescent bulb is made of tungsten, which has a very high melting point.", "The heating elements of electric irons and heaters are made of copper, because copper has a high resistance."], "statements_hi": ["तापदीप्त बल्ब का तंतु (filament) टंगस्टन का बना होता है, जिसका गलनांक बहुत ऊँचा है।", "विद्युत इस्त्री और हीटरों के तापन अवयव ताँबे के बनाए जाते हैं, क्योंकि ताँबे का प्रतिरोध अधिक होता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: tungsten, which melts at about 3,380 degrees Celsius, can glow white-hot without melting, though most of the energy of such a bulb is still lost as heat. Statement 2 is wrong: copper has a very low resistance, which is why it is used for connecting wires; heating elements are made of alloys such as nichrome, which have a high resistance and do not oxidise readily at high temperatures.','केवल कथन 1 सही है: लगभग 3,380 डिग्री सेल्सियस पर पिघलने वाला टंगस्टन बिना पिघले श्वेत-तप्त होकर चमक सकता है, यद्यपि ऐसे बल्ब की अधिकांश ऊर्जा अब भी ऊष्मा के रूप में नष्ट होती है। कथन 2 गलत है: ताँबे का प्रतिरोध बहुत कम है, इसीलिए वह जोड़ने वाले तारों में प्रयुक्त होता है; तापन अवयव नाइक्रोम जैसी मिश्रधातुओं के बनते हैं, जिनका प्रतिरोध अधिक होता है और जो ऊँचे तापमान पर आसानी से ऑक्सीकृत नहीं होतीं।','l1-sci-tungsten-nichrome-heating','original_pattern_matched','NCERT Class X, Science (Electricity).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','statement_based','hard','Consider the following statements about sound:','ध्वनि के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["To hear a distinct echo, the reflecting surface must be at least about 17 metres away from the listener.", "Sound travels faster in solids than in air.", "The human ear can hear sounds with frequencies from about 2 Hz to about 2,000 Hz."], "statements_hi": ["स्पष्ट प्रतिध्वनि सुनने के लिए परावर्तक सतह श्रोता से कम से कम लगभग 17 मीटर दूर होनी चाहिए।", "ध्वनि वायु की तुलना में ठोसों में तेज़ चलती है।", "मानव कान लगभग 2 हर्ट्ज़ से लगभग 2,000 हर्ट्ज़ तक की आवृत्ति वाली ध्वनियाँ सुन सकता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the sensation of a sound persists in the brain for about 0.1 second, so the echo must return at least that much later -- at about 344 metres a second, sound covers 34.4 metres in that time, there and back, which puts the wall at least 17.2 metres away. Statement 3 is wrong: the audible range is roughly 20 Hz to 20,000 Hz; sounds below it are infrasound, which elephants and whales use, and above it ultrasound, used in medical scans.','कथन 1 और 2 सही हैं: ध्वनि की संवेदना मस्तिष्क में लगभग 0.1 सेकंड रहती है, इसलिए प्रतिध्वनि को कम से कम इतनी देर बाद लौटना चाहिए -- लगभग 344 मीटर प्रति सेकंड पर ध्वनि इस समय में जाने-आने में 34.4 मीटर चलती है, जिससे दीवार कम से कम 17.2 मीटर दूर होनी चाहिए। कथन 3 गलत है: श्रव्य परास लगभग 20 हर्ट्ज़ से 20,000 हर्ट्ज़ है; उससे नीचे अवश्रव्य ध्वनि है, जिसका हाथी और व्हेल उपयोग करते हैं, और ऊपर पराश्रव्य ध्वनि, जो चिकित्सा जाँचों में प्रयुक्त होती है।','l1-sci-echo-distance-audible-range','original_pattern_matched','NCERT Class IX, Science (Sound).','draft'),
('upsc','Science & Technology','Physics & Everyday Science','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "A person with myopia can see distant objects clearly but not nearby ones.", "assertion_hi": "निकट-दृष्टि दोष (myopia) वाला व्यक्ति दूर की वस्तुएँ स्पष्ट देख सकता है पर निकट की नहीं।", "reason": "In myopia, the image of a distant object is formed in front of the retina.", "reason_hi": "निकट-दृष्टि दोष में दूर की वस्तु का प्रतिबिंब रेटिना के आगे बनता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. Myopia is near-sightedness: nearby objects are seen clearly but distant ones look blurred, because the eye lens is too strongly curved or the eyeball too long, so light from far away comes to a focus before it reaches the retina; a concave (diverging) lens corrects it. The opposite defect, hypermetropia or far-sightedness, makes near objects blurred and is corrected with a convex lens.','कथन-I गलत है, पर कथन-II सही है। निकट-दृष्टि दोष में निकट की वस्तुएँ स्पष्ट पर दूर की धुँधली दिखती हैं, क्योंकि नेत्र लेंस अधिक वक्रित या नेत्र गोलक लंबा होता है, इसलिए दूर से आया प्रकाश रेटिना तक पहुँचने से पहले ही फ़ोकस हो जाता है; अवतल (अपसारी) लेंस इसे ठीक करता है। उलटा दोष, दीर्घ-दृष्टि (hypermetropia), निकट की वस्तुओं को धुँधला बनाता है और उत्तल लेंस से ठीक होता है।','l1-sci-myopia-image-before-retina','original_pattern_matched','NCERT Class X, Science (The Human Eye and the Colourful World).','draft')
